/**
 * JsonTree.Entry: one value of the tree, a leaf or a container with its entries.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/json-tree.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { type JSX } from 'solid-js'

import { Each, Icon, claimSlot, createCell, createDerived, scope } from '@polymorph/solid'
import styles from '@polymorph/recipes/structure/json-tree.module.css'

export interface JsonTreeEntryProps {
  /**
   * The key or index it sits under.
   */
  name?: string
  value: unknown
  depth: number
  defaultDepth: number
}

/** JsonTree.Entry: one value of the tree, a leaf or a container with its entries. */
export default function JsonTreeEntry(given: JsonTreeEntryProps): JSX.Element {
  const props = claimSlot(given)
  return scope(() => {
    const open = createCell(props.depth < props.defaultDepth)
    const entries = createDerived(() =>
      typeof props.value === 'object' && props.value !== null
        ? Array.isArray(props.value)
          ? props.value.map((item: unknown, index: number) => [String(index), item] as const)
          : Object.entries(props.value)
        : null,
    )
    const kind = createDerived(() =>
      props.value === null
        ? 'null'
        : typeof props.value === 'string'
          ? 'string'
          : typeof props.value === 'number'
            ? 'number'
            : typeof props.value === 'boolean'
              ? 'boolean'
              : 'null',
    )
    const spelled = createDerived(() =>
      kind.value === 'string' ? JSON.stringify(props.value) : String(props.value),
    )
    const summary = createDerived(() =>
      Array.isArray(props.value)
        ? `[…] ${props.value.length} ${props.value.length === 1 ? 'item' : 'items'}`
        : `{…} ${entries.value?.length ?? 0} ${entries.value?.length === 1 ? 'key' : 'keys'}`,
    )
    return (
      <>
        {entries.value === null ? (
          <li class={styles.row}>
            {props.name !== undefined ? (
              <span class={styles.key}>
                {props.name}
                <span class={styles.colon}>:</span>
              </span>
            ) : null}
            {/* value */}
            <span class={styles.value} data-kind={kind.value}>
              {spelled.value}
            </span>
          </li>
        ) : entries.value.length === 0 ? (
          <li class={styles.row}>
            {props.name !== undefined ? (
              <span class={styles.key}>
                {props.name}
                <span class={styles.colon}>:</span>
              </span>
            ) : null}
            {/* summary */}
            <span class={styles.summary}>{Array.isArray(props.value) ? '[]' : '{}'}</span>
          </li>
        ) : (
          <li class={styles.row}>
            {/* toggle */}
            <button
              class={styles.toggle}
              type="button"
              aria-expanded={open.value}
              onclick={() => (open.value = !open.value)}
            >
              {/* chevron */}
              <span class={styles.chevron} aria-hidden="true">
                <Icon name="next" size="sm" />
              </span>
              {props.name !== undefined ? (
                <span class={styles.key}>
                  {props.name}
                  <span class={styles.colon}>:</span>
                </span>
              ) : null}
              {/* summary */}
              <span class={styles.summary}>{summary.value}</span>
            </button>
            {open.value ? (
              <ul class={styles.children}>
                <Each of={entries.value} by={(pair) => pair[0]} renew>
                  {(pair) => (
                    <JsonTreeEntry
                      name={pair[0]}
                      value={pair[1]}
                      depth={props.depth + 1}
                      defaultDepth={props.defaultDepth}
                    />
                  )}
                </Each>
              </ul>
            ) : null}
          </li>
        )}
      </>
    )
  })
}
